// Holds the data models (entities) that EF Core maps to database tables
namespace LibraryService.Models;

/// <summary>
/// One row of the Favorites table: a game saved by a browser, plus a snapshot
/// of the game's data taken from catalog-service at the moment it was added.
/// </summary>
public class Favorite
{
    /// <summary>Primary key, generated by SQL Server.</summary>
    public int Id { get; set; }

    /// <summary>The user's ID: the "sub" claim of the JWT issued by auth-service (an Identity user ID, a string).</summary>
    public string UserId { get; set; } = string.Empty;

    /// <summary>The IGDB game ID, same value catalog-service uses.</summary>
    public int GameId { get; set; }

    // Snapshot: a copy of the game's data, so the list shows without calling catalog-service.
    public string Name { get; set; } = string.Empty;
    public string? CoverUrl { get; set; }
    public double? Rating { get; set; }
    public DateOnly? ReleaseDate { get; set; }

    /// <summary>Platform groups (PC, PlayStation...) as JSON text, saved with the snapshot. See PlatformJson.</summary>
    public string? ParentPlatformsJson { get; set; }

    /// <summary>When the game was added (UTC). Used to sort the list, newest first.</summary>
    public DateTimeOffset AddedAt { get; set; }
}
